<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {listDevices,getMonitoring} from '$lib/api.js';import {locale} from '$lib/i18n.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let loading=true;let items=[];let metrics={};let search='';let statusFilter='all';let limit=1;\n $: ru=$locale!=='en';\n $: filtered=items.filter(d=>{const q=search.trim().toLowerCase();if(q&&!(d.hostname+' '+d.device_id+' '+d.platform+' '+d.architecture).toLowerCase().includes(q))return false;if(statusFilter!=='all'&&d.status!==statusFilter)return false;return true});
 onMount(async()=>{const [r,m]=await Promise.all([listDevices($page.url.searchParams.get('project_id')||''),getMonitoring($page.url.searchParams.get('project_id')||'')]);if(r.ok){items=r.data.devices||[];limit=r.data.limit||1}else notify(r.error||'Не удалось загрузить устройства','error');if(m.ok)for(const d of m.data.devices||[])metrics[d.id]=d.metrics||{};loading=false});
</script>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE</div><h1 class="page-title">{ru?'Устройства':'Devices'}</h1><p class="page-desc">{ru?'Управляй серверами и устройствами, подключёнными к Yevqo.':'Manage all servers and devices connected to Yevqo.'}</p></div><Button variant="primary" on:click={()=>goto('/overview')}>{ru?'Подключить устройство':'Connect device'}</Button></div>
<div class="summary"><div><strong>{items.length} / {limit}</strong><span>{ru?'Устройств подключено':'Connected devices'}</span></div><div><strong>{items.filter(x=>x.status==='online').length}</strong><span>{ru?'Сейчас онлайн':'Online now'}</span></div></div>
{#if items.length>=limit}<div class="limit-notice"><strong>{ru?'Лимит подключений достигнут':'Device limit reached'}</strong><span>{ru?'Бесплатный тариф включает одно устройство. Отвяжи старое устройство, чтобы подключить новое.':'The Free plan includes one device. Unpair the existing device before connecting another one.'}</span></div>{/if}
{#if loading}<div class="empty">Загрузка устройств…</div>{:else if !items.length}<div class="empty"><p>{ru?'Устройств пока нет':'No devices connected yet'}</p><p>{ru?'Подключи Android Agent через Termux, чтобы начать работу.':'Install the Android Agent through Termux to get started.'}</p><div class="actions"><Button variant="primary" on:click={()=>goto('/overview')}>{ru?'Инструкция по подключению':'Installation instructions'}</Button></div></div>{:else}
<div class="device-toolbar"><input class="input" bind:value={search} placeholder={ru?'Поиск устройств…':'Search devices…'}/><select class="input" bind:value={statusFilter}><option value="all">{ru?'Все статусы':'All statuses'}</option><option value="online">Online</option><option value="offline">Offline</option></select></div>
{#if !filtered.length}<div class="empty">{ru?'Устройства не найдены.':'No devices found.'}</div>{:else}<div class="device-list"><div class="device-head"><span>{ru?'Устройство':'Device'}</span><span>OS / Agent</span><span>CPU / RAM</span><span>{ru?'Последнее подключение':'Last connected'}</span><span>{ru?'Статус':'Status'}</span></div>{#each filtered as d (d.id)}<button class="device-row" on:click={()=>goto('/devices/'+d.id+($page.url.searchParams.get('project_id')?'?project_id='+$page.url.searchParams.get('project_id'):''))}><span class="device-main"><strong>{d.hostname||d.device_id?.slice(0,8)||'Android host'}</strong><small>{d.device_id?.slice(0,18)||'—'}</small></span><span class="device-os">{d.platform||'—'} / {d.architecture||'—'}<small>Agent {d.agent_version||'—'}</small></span><span class="device-os">{metrics[d.id]?.cpu_percent!=null?metrics[d.id].cpu_percent.toFixed(1)+'%':'—'} / {metrics[d.id]?.memory_available_bytes!=null?(metrics[d.id].memory_available_bytes/1073741824).toFixed(2)+' GB free':'—'}</span><span class="device-os">{d.last_seen?new Date(d.last_seen).toLocaleString():'—'}</span><span class="device-state"><StatusDot status={d.status}/>{d.status==='online'?'Online':'Offline'}</span></button>{/each}</div>{/if}{/if}
<style>
.device-toolbar{display:flex;gap:8px;margin-bottom:10px}.device-toolbar input{flex:1}.device-toolbar select{width:auto;min-width:140px}.device-head{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr .7fr;gap:10px;padding:10px 14px;border-bottom:1px solid var(--border);color:var(--text-muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.device-os{display:grid;gap:3px;min-width:0;font-size:10px;color:var(--text-main)}.device-os small{font-size:9px;color:var(--text-muted)}.eyebrow{font-size:9px;font-weight:700;letter-spacing:.14em;color:#818cf8;margin-bottom:7px}.summary{display:flex;gap:10px;margin-bottom:14px}.summary>div{display:flex;align-items:baseline;gap:8px;padding:12px 15px;background:#101727;border:1px solid #253149;border-radius:10px}.summary strong{font-size:18px}.summary span{font-size:10px;color:#64748b}.device-list{border:1px solid #253149;border-radius:12px;overflow:hidden;background:#101727}.device-row{width:100%;display:flex;align-items:center;gap:13px;padding:13px 15px;background:transparent;border:0;border-bottom:1px solid #1e293b;text-align:left;color:#f1f5f9}.device-row:last-child{border:0}.device-row:hover{background:#172136}.device-icon{width:31px;height:31px;display:grid;place-items:center;border-radius:8px;background:#1b2740;color:#a5b4fc}.device-main{display:flex;flex-direction:column;flex:1;min-width:0}.device-main strong{font-size:11px}.device-main small{font:9px 'JetBrains Mono',monospace;color:#64748b;overflow:hidden;text-overflow:ellipsis}.device-ip,.device-state{font-size:10px;color:#94a3b8}.device-state{display:flex;align-items:center;gap:7px}.arrow{color:#64748b}.actions{margin-top:16px}.limit-notice{display:flex;flex-direction:column;gap:5px;margin:0 0 14px;padding:12px 14px;border:1px solid #66522c;background:#2b2418;border-radius:10px;color:#f3d69b;font-size:11px}.limit-notice span{color:#b9a77f;font-size:10px;line-height:1.5}@media(max-width:760px){.device-head{display:none}.device-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.device-main{grid-column:1/-1}.device-state{justify-content:flex-end}.device-toolbar{flex-wrap:wrap}.device-toolbar input{flex-basis:100%}.device-toolbar select{flex:1}}@media(max-width:650px){.page-header{align-items:stretch}}
</style>